let current=models[0],selected=12,zoom=1,view=[],drag=null;
const $=id=>document.getElementById(id),ns='http://www.w3.org/2000/svg';
function svgEl(tag,attrs){const e=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));return e}
function applyView(){ $('diagram').setAttribute('viewBox',view.join(' '));$('reset').textContent=Math.round(zoom*100)+'%'}
function reset(){zoom=1;view=[...current.view];applyView()}
function renderModel(){ $('models').innerHTML=models.map(m=>`<button class="${m.id===current.id?'active':''}" aria-pressed="${m.id===current.id}" data-model="${m.id}"><b>0${m.id} &nbsp; ${m.name}</b><small>${m.parts.length} ta pozitsiya · ${m.id===3?'Elektr asbob':'Changyutgich'}</small></button>`).join('');$('modelTitle').textContent=current.name;const svg=$('diagram');svg.replaceChildren();svg.append(svgEl('image',{href:current.image,x:0,y:0,width:current.size[0],height:current.size[1]}));const r=current.id===1?5.8:12;current.parts.forEach(p=>{const g=svgEl('g',{class:'hotspot',tabindex:0,role:'button','aria-label':`${p.id}: ${p.name}`,'data-id':p.id});g.append(svgEl('circle',{cx:p.x,cy:p.y,r}));const t=svgEl('text',{x:p.x,y:p.y,'font-size':r*1.14});t.textContent=p.id;g.append(t);g.addEventListener('click',()=>select(p.id,true));g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(p.id,true)}});svg.append(g)});$('search').value='';reset();select(selected);}
function select(id,scroll=false){selected=id;const p=current.parts.find(p=>p.id===id);$('detail').innerHTML=`<div class="selected-label"><span class="position">${p.id}</span> TANLANGAN POZITSIYA</div><h2>${p.name}</h2><div class="article-label">ARTIKUL</div><div class="article">${p.article}</div><span class="badge">${p.demoArticle?'Shartli demo artikul':'Chizmadagi kod / standart'}</span><div class="price-row"><div><div class="price">${new Intl.NumberFormat('uz-UZ').format(p.price)} <small>so‘m</small></div><div class="caption">1 dona uchun · demo narx</div></div><span class="badge">Namuna</span></div>`;document.querySelectorAll('.hotspot').forEach(g=>g.classList.toggle('selected',+g.dataset.id===id));renderList();if(scroll&&window.innerWidth<731)$('detail').scrollIntoView({behavior:'smooth',block:'start'});}
function renderList(){const q=$('search').value.toLocaleLowerCase();const parts=current.parts.filter(p=>`${p.id} ${p.name} ${p.article}`.toLocaleLowerCase().includes(q));$('resultCount').textContent=`${parts.length} ta`;$('parts').innerHTML=parts.length?parts.map(p=>`<button class="part ${p.id===selected?'active':''}" data-part="${p.id}"><span class="part-num">${p.id}</span><span><b>${p.name}</b><small>${p.article}</small></span></button>`).join(''):'<p>Detal topilmadi.</p>'}
$('models').addEventListener('click',e=>{const b=e.target.closest('[data-model]');if(b){current=models.find(m=>m.id===+b.dataset.model);selected=current.id===3?6:12;renderModel()}});$('parts').addEventListener('click',e=>{const b=e.target.closest('[data-part]');if(b)select(+b.dataset.part)});$('search').addEventListener('input',renderList);
function zoomBy(f){const next=Math.min(4,Math.max(1,zoom*f));const ratio=zoom/next;view=[view[0]+view[2]*(1-ratio)/2,view[1]+view[3]*(1-ratio)/2,view[2]*ratio,view[3]*ratio];zoom=next;applyView()}
$('plus').onclick=()=>zoomBy(1.3);$('minus').onclick=()=>zoomBy(1/1.3);$('reset').onclick=reset;$('source').onclick=()=>{$('originalImage').src=current.image;$('original').showModal()};$('close').onclick=()=>$('original').close();
const svg=$('diagram');svg.addEventListener('pointerdown',e=>{if(e.target.closest('.hotspot'))return;const m=svg.getScreenCTM();drag={x:e.clientX,y:e.clientY,view:[...view],scale:m.a};svg.setPointerCapture(e.pointerId)});svg.addEventListener('pointermove',e=>{if(!drag)return;view=[drag.view[0]-(e.clientX-drag.x)/drag.scale,drag.view[1]-(e.clientY-drag.y)/drag.scale,drag.view[2],drag.view[3]];applyView()});svg.addEventListener('pointerup',()=>drag=null);svg.addEventListener('pointercancel',()=>drag=null);renderModel();
